def min_window(S, T):
    n, m = len(S), len(T)

    def is_subsequence(window):
        j = 0
        for c in window:
            if j < m and c == T[j]:
                j += 1
        return j == m

    best = ""
    for start in range(n):
        for end in range(start + 1, n + 1):
            window = S[start:end]                                          # try every possible contiguous window directly
            if is_subsequence(window):
                if best == "" or len(window) < len(best):
                    best = window
                break                                                        # any longer window from this same start is never shorter
    return best


if __name__ == "__main__":
    print(min_window("abcdebdde", "bde"))

