import java.util.*;

public class Main {
    String minWindow(String S, String T) {
        int n = S.length(), m = T.length();
        String best = "";
        for (int start = 0; start < n; start++) {
            for (int end = start + 1; end <= n; end++) {
                String window = S.substring(start, end);                          // try every possible contiguous window directly
                if (isSubsequence(window, T)) {
                    if (best.isEmpty() || window.length() < best.length()) best = window;
                    break;                                                          // any longer window from this same start is never shorter
                }
            }
        }
        return best;
    }

    boolean isSubsequence(String window, String t) {
        int j = 0;
        for (char c : window.toCharArray()) {
            if (j < t.length() && c == t.charAt(j)) j++;
        }
        return j == t.length();
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minWindow("abcdebdde", "bde"));
    }
}

