import java.util.*;

public class Main {
    String minWindow(String S, String T) {
        int n = S.length(), m = T.length();
        int bestStart = -1, bestLen = Integer.MAX_VALUE;
        int i = 0;
        while (i < n) {
            int j = 0;
            if (S.charAt(i) == T.charAt(j)) {                                     // found where a candidate match of T could start
                int start = i;
                while (i < n && j < m) {
                    if (S.charAt(i) == T.charAt(j)) j++;                            // advance through T as S is scanned forward
                    i++;
                }
                if (j == m) {                                                       // all of T matched as a subsequence, ending just before i
                    int end = i;
                    j--;
                    int k = end - 1;
                    while (j >= 0) {                                                  // scan backward, matching T in reverse to find the tightest start
                        if (S.charAt(k) == T.charAt(j)) j--;
                        k--;
                    }
                    int windowStart = k + 1;
                    int windowLen = end - windowStart;
                    if (windowLen < bestLen) {
                        bestLen = windowLen;
                        bestStart = windowStart;
                    }
                    i = windowStart + 1;                                             // resume the search just past this window's start
                } else {
                    break;                                                            // not enough characters left in S to complete T
                }
            } else {
                i++;
            }
        }
        return bestStart == -1 ? "" : S.substring(bestStart, bestStart + bestLen);
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.minWindow("abcdebdde", "bde"));
    }
}

